function auctionNumbers(input=rows){
  const cut=Math.max(10,Math.min(20,Math.floor(input.length*2/3)));
  const valid=research(3,input,cut);
  let oracle=1; // Deliberately invalid example: chooses exposure after seeing the next open.
  for(let i=cut;i<input.length-1;i++)oracle*=1+Math.max(0,input[i+1].open/input[i].open-1);
  const exploration=input.slice(0,cut),inner=Math.max(4,Math.floor(cut/2));
  const trials=Array.from({length:Math.min(5,inner-1)-1},(_,i)=>({n:i+2,r:research(i+2,exploration,inner).ret}));
  const best=trials.reduce((a,b)=>b.r>a.r?b:a);
  return {valid,oracle:(oracle-1)*100,best,trials,cut};
}
